-- CheckMate PostgreSQL schema. Stores consent evidence, verification outcomes, and behavior bands only.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('tenant', 'operator');
CREATE TYPE verification_type AS ENUM ('identity', 'affiliation');
CREATE TYPE gender_type AS ENUM ('female', 'male', 'non_binary', 'prefer_not_to_say');
CREATE TYPE contract_status AS ENUM ('confirmed', 'cancelled');
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL, pseudonym VARCHAR(80) NOT NULL, age SMALLINT CHECK(age BETWEEN 18 AND 100), gender gender_type, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE operator_rooms (operator_id VARCHAR(80) NOT NULL, room_id VARCHAR(80) NOT NULL, PRIMARY KEY(operator_id, room_id));
CREATE TABLE funnel_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operator_id VARCHAR(80) NOT NULL, room_id VARCHAR(80) NOT NULL, funnel_id UUID NOT NULL, step VARCHAR(40) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX funnel_events_operator_step_idx ON funnel_events(operator_id, step, created_at);
CREATE TABLE consents (user_id UUID PRIMARY KEY REFERENCES users(id), version VARCHAR(20) NOT NULL, agreed_at TIMESTAMPTZ NOT NULL, evidence_digest CHAR(64) NOT NULL);
CREATE TABLE verification_results (user_id UUID REFERENCES users(id), type verification_type NOT NULL, provider VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, evidence_digest CHAR(64) NOT NULL, verified_at TIMESTAMPTZ, PRIMARY KEY(user_id, type));
CREATE TABLE behavior_profiles (user_id UUID PRIMARY KEY REFERENCES users(id), late_return_band SMALLINT CHECK(late_return_band BETWEEN 0 AND 3), delivery_waste_band SMALLINT CHECK(delivery_waste_band BETWEEN 0 AND 3), guest_frequency_band SMALLINT CHECK(guest_frequency_band BETWEEN 0 AND 3), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE matching_rules (rule_key VARCHAR(80) PRIMARY KEY, weight NUMERIC(6,2) NOT NULL, max_distance SMALLINT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE matches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), member_a_id UUID REFERENCES users(id), member_b_id UUID REFERENCES users(id), compatibility_score SMALLINT CHECK(compatibility_score BETWEEN 0 AND 100), score_breakdown JSONB NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'proposed', accepted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), match_id UUID REFERENCES matches(id), amount_krw INTEGER NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ready', provider_payment_key_hash CHAR(64), idempotency_key UUID NOT NULL UNIQUE, paid_at TIMESTAMPTZ);
CREATE TABLE ephemeral_chat_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), match_id UUID REFERENCES matches(id), expires_at TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), operator_id VARCHAR(80) NOT NULL, room_id VARCHAR(80) NOT NULL, move_in_date DATE NOT NULL, status contract_status NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE post_care_checkins (contract_id UUID PRIMARY KEY REFERENCES contracts(id), due_at TIMESTAMPTZ NOT NULL, sent_at TIMESTAMPTZ, responded_at TIMESTAMPTZ, satisfaction SMALLINT CHECK(satisfaction BETWEEN 1 AND 5), conflict BOOLEAN, outcome_label VARCHAR(40));
CREATE TABLE digital_agreements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), match_id UUID REFERENCES matches(id), room_id VARCHAR(80) NOT NULL, rules JSONB NOT NULL, signatures JSONB NOT NULL DEFAULT '{}', status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE mediation_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id UUID REFERENCES users(id), operator_id VARCHAR(80) NOT NULL, room_id VARCHAR(80) NOT NULL, match_id UUID REFERENCES matches(id), agreement_id UUID REFERENCES digital_agreements(id), category VARCHAR(60) NOT NULL, description TEXT NOT NULL, severity VARCHAR(20) NOT NULL DEFAULT 'medium', status VARCHAR(30) NOT NULL DEFAULT 'open', sequence_no INTEGER NOT NULL DEFAULT 1, guarantee_status VARCHAR(30) NOT NULL DEFAULT 'none', webhook_notified_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX mediation_tickets_room_status_idx ON mediation_tickets(room_id, status, created_at);
CREATE TABLE feedback_labels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), contract_id UUID REFERENCES contracts(id), user_id UUID REFERENCES users(id), checkpoint SMALLINT CHECK(checkpoint IN (30,90)), satisfaction SMALLINT CHECK(satisfaction BETWEEN 1 AND 5), conflict BOOLEAN NOT NULL DEFAULT false, early_exit BOOLEAN NOT NULL DEFAULT false, label VARCHAR(40) NOT NULL, conflict_categories JSONB NOT NULL DEFAULT '[]', behavior_snapshot JSONB, chat_features JSONB, pattern_key CHAR(64), label_version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX feedback_labels_training_idx ON feedback_labels(pattern_key, label, created_at);
CREATE TABLE outcome_pattern_aggregates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pattern_key CHAR(64) NOT NULL UNIQUE, feature_summary JSONB NOT NULL, category_counts JSONB NOT NULL DEFAULT '{}', total_samples INTEGER NOT NULL DEFAULT 0, conflict_samples INTEGER NOT NULL DEFAULT 0, stable_samples INTEGER NOT NULL DEFAULT 0, satisfaction_sum INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX outcome_pattern_aggregates_conflict_idx ON outcome_pattern_aggregates(conflict_samples, total_samples);
CREATE TABLE chat_behavior_metrics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), chat_session_id UUID REFERENCES ephemeral_chat_sessions(id), tenant_id UUID REFERENCES users(id), first_message_at TIMESTAMPTZ, first_response_latency_ms INTEGER, average_response_latency_ms INTEGER, sent_message_count INTEGER NOT NULL DEFAULT 0, received_message_count INTEGER NOT NULL DEFAULT 0, active_seconds INTEGER NOT NULL DEFAULT 0, acceptance_latency_ms INTEGER, proactivity_score SMALLINT CHECK(proactivity_score BETWEEN 0 AND 100), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, UNIQUE(chat_session_id, tenant_id));
CREATE INDEX chat_behavior_metrics_tenant_score_idx ON chat_behavior_metrics(tenant_id, proactivity_score);
